const msg = $input.item.json;

function cleanEmail(value) {
  if (!value) return null;

  const str = String(value);
  const match = str.match(/<([^>]+)>/);

  return (match ? match[1] : str)
    .trim()
    .toLowerCase();
}

function stripHtml(html) {
  if (!html) return "";
  return String(html)
    .replace(/<style[\s\S]*?<\/style>/gi, "")
    .replace(/<script[\s\S]*?<\/script>/gi, "")
    .replace(/<[^>]+>/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

const fromRaw =
  msg.from ||
  msg.From ||
  msg.sender ||
  msg.headers?.from ||
  "";

const toRaw =
  msg.to ||
  msg.To ||
  msg.recipient ||
  msg.headers?.to ||
  "";

const subject =
  msg.subject ||
  msg.Subject ||
  "";

const providerMessageId =
  msg.id ||
  msg.messageId ||
  msg.message_id ||
  msg.headers?.["message-id"] ||
  null;

const providerThreadId =
  msg.threadId ||
  msg.thread_id ||
  msg.conversationId ||
  null;

const bodyRaw =
  msg.textPlain ||
  msg.text ||
  msg.plainText ||
  msg.body ||
  stripHtml(msg.textHtml || msg.html || "");

let replyBody = String(bodyRaw || "")
  .replace(/\r/g, "")
  .split(/\nOn .*wrote:\n/i)[0]
  .split(/\nFrom: .*/i)[0]
  .trim();

if (replyBody.length > 3000) {
  replyBody = replyBody.slice(0, 3000);
}

const fromEmail = cleanEmail(fromRaw);
const toEmail = cleanEmail(toRaw);

const noiseSenders = [
  "mailer-daemon",
  "postmaster",
  "no-reply",
  "noreply",
  "donotreply",
  "do-not-reply"
];

const isNoise =
  !fromEmail ||
  noiseSenders.some(s => fromEmail.includes(s)) ||
  /delivery status notification|undelivered mail|mail delivery/i.test(subject);

return {
  json: {
    from_email: fromEmail,
    to_email: toEmail,
    subject,
    reply_body: replyBody,
    provider_message_id: providerMessageId,
    provider_thread_id: providerThreadId,
    is_noise: isNoise
  }
};

