const previous = $("Attach Reply Event ID").first().json;
const response = $input.item.json;

const allowedIntents = [
  "positive_interest",
  "neutral_question",
  "objection",
  "not_interested",
  "unsubscribe",
  "out_of_office",
  "wrong_person",
  "bounce",
  "manual_review_required"
];

const allowedSentiments = [
  "positive",
  "neutral",
  "negative"
];

function safeString(value, fallback = "") {
  if (value === null || value === undefined) return fallback;
  return String(value).trim();
}

let parsed = null;
let parseError = null;

try {
  const content = response.choices?.[0]?.message?.content;

  if (typeof content === "string") {
    parsed = JSON.parse(content);
  } else if (typeof content === "object" && content !== null) {
    parsed = content;
  } else {
    parseError = "missing_classifier_content";
  }
} catch (error) {
  parseError = "classifier_response_not_valid_json";
}

const intentRaw = safeString(parsed?.intent_classification, "manual_review_required");
const sentimentRaw = safeString(parsed?.sentiment, "neutral");

const intent = allowedIntents.includes(intentRaw)
  ? intentRaw
  : "manual_review_required";

const sentiment = allowedSentiments.includes(sentimentRaw)
  ? sentimentRaw
  : "neutral";

const humanReviewIntents = [
  "positive_interest",
  "neutral_question",
  "objection",
  "wrong_person",
  "manual_review_required"
];

const requiresHumanReview =
  typeof parsed?.requires_human_review === "boolean"
    ? parsed.requires_human_review
    : humanReviewIntents.includes(intent);

return {
  json: {
    ...previous,
    intent_classification: intent,
    sentiment,
    requires_human_review: requiresHumanReview,
    summary: safeString(
      parsed?.summary,
      parseError ? `Classifier fallback used: ${parseError}` : ""
    ),
    suggested_next_action: safeString(
      parsed?.suggested_next_action,
      "Review the reply manually before taking action."
    ),
    suggested_reply_draft: safeString(parsed?.suggested_reply_draft, ""),
    classifier_parse_error: parseError,
    raw_classifier_response: parsed || null
  }
};

const normalized = $("Normalize Message").first().json;
const matchRaw = $input.item.json;

const match = Array.isArray(matchRaw) ? matchRaw[0] : matchRaw;

if (!match?.lead_id) {
  return {
    json: {
      ...normalized,
      matched: false,
      match_error: "no_lead_match"
    }
  };
}

return {
  json: {
    ...normalized,
    matched: true,
    lead_id: match.lead_id,
    business_name: match.business_name,
    lead_email: match.lead_email,
    matched_by: match.matched_by
  }
};

const previous = $("Prepare Matched Reply").first().json;
const raw = $input.item.json;

const row = Array.isArray(raw) ? raw[0] : raw;

return {
  json: {
    ...previous,
    reply_event_id: row.reply_event_id || row.id || null
  }
};
